        queue = [(start, [start])]
        while queue:
            node, path = queue.pop(0)
            for neighbor in graph.get(node, []):
                if neighbor not in path:
                    queue.append((neighbor, path + [neighbor]))
                    if neighbor == goal:
                        return path + [neighbor]
        return None
    paths = {}
    for node in graph:
        paths[node] = bfs(graph, node)
    if start not in graph or goal not in graph:
        return None
